# Pure Python-এ Sequence Tensor Shape Contract ও B=1 Squeeze ফাঁদ যাচাই
def recurrent_shapes(B, T, F, H, num_layers=1, bidirectional=False, batch_first=True):
    D = 2 if bidirectional else 1
    if batch_first:
        x_shape = (B, T, F)
        out_shape = (B, T, D * H)
    else:
        x_shape = (T, B, F)
        out_shape = (T, B, D * H)
    # সাবধান: batch_first যা-ই হোক, h_n সবসময় (L * D, B, H)!
    h_n_shape = (num_layers * D, B, H)
    return x_shape, out_shape, h_n_shape

# ১) 2-layer Bidirectional LSTM উদাহরণ
x_s, out_s, hn_s = recurrent_shapes(B=4, T=5, F=2, H=3, num_layers=2, bidirectional=True)
print('2L Bi-LSTM -> x:', x_s, '| output:', out_s, '| h_n:', hn_s)

# ২) আমাদের Bike Sharing 1-layer Unidirectional GRU
gx, gout, ghn = recurrent_shapes(B=2, T=14, F=1, H=3, num_layers=1, bidirectional=False)
print('Bike GRU   -> x:', gx, '| output:', gout, '| h_n:', ghn)

# ৩) Safe squeeze(-1) বনাম Unsafe squeeze() যখন B=4 বনাম B=1!
def safe_squeeze_last(shape):
    if len(shape) > 0 and shape[-1] == 1:
        return shape[:-1]
    return shape

def unsafe_squeeze_all(shape):
    kept = []
    for dim in shape:
        if dim != 1:
            kept.append(dim)
    return tuple(kept)

for head_shape in [(4, 1), (1, 1)]:
    print('Head', head_shape, '-> safe squeeze(-1):', safe_squeeze_last(head_shape), '| unsafe squeeze():', unsafe_squeeze_all(head_shape))

# Pure Python-এ RNN, GRU, LSTM Parameter তুলনা ও Budget-Matched Hidden Size খোঁজা
def cell_params(kind, F, H):
    mult_map = {'rnn': 1, 'gru': 3, 'lstm': 4}
    return mult_map[kind] * H * (F + H + 2)

# ১) আমাদের অধ্যায়ের F=1, H=3 সেটআপ
counts = {}
for name in ['rnn', 'gru', 'lstm']:
    counts[name] = cell_params(name, F=1, H=3)
assert counts == {'rnn': 18, 'gru': 54, 'lstm': 72}
print('F=1, H=3 cell params:', counts)

# ২) একই ~1000 Parameter বাজেটে কার Hidden Size H কত বড় হতে পারে? (F=1)
budget = 1000
for name in ['rnn', 'gru', 'lstm']:
    best_h = 1
    best_p = cell_params(name, 1, 1)
    for h in range(1, 100):
        p = cell_params(name, 1, h)
        if p <= budget:
            best_h = h
            best_p = p
    print(f'Budget <= {budget} | {name.upper():4s} -> max H = {best_h:2d} (params = {best_p})')

# ৩) Bike Sharing Dev MAE গ্যাপ (GRU বনাম Naive Baseline)
mae_naive = 900.6044
mae_gru = 1245.9109
pct_worse = 100.0 * (mae_gru - mae_naive) / mae_naive
print(f'Fixed GRU MAE is +{mae_gru - mae_naive:.2f} counts ({pct_worse:.1f}% higher) than Naive')

# Pure Python-এ Masked Loss: Valid-token Mean, Per-sequence Mean ও NaN*0 সুরক্ষা
import math

losses_clean = [[1.0, 3.0, 99.0], [2.0, 4.0, 6.0]]
losses_with_nan = [[1.0, 3.0, float('nan')], [2.0, 4.0, 6.0]]
mask = [[1, 1, 0], [1, 1, 1]]

# ১) Unsafe গুণফল পদ্ধতি: NaN * 0.0 -> NaN!
unsafe_sum = 0.0
for r in range(len(losses_with_nan)):
    for c in range(len(losses_with_nan[r])):
        unsafe_sum += losses_with_nan[r][c] * float(mask[r][c])
print('Unsafe (losses * mask) with NaN in pad:', unsafe_sum, '| is NaN:', math.isnan(unsafe_sum))

# ২) Safe Boolean-Filtered Valid-token Mean (NaN pad থাকলেও সম্পূর্ণ নিরাপদ!)
def valid_token_mean(loss_grid, mask_grid):
    total = 0.0
    count = 0
    for r in range(len(loss_grid)):
        for c in range(len(loss_grid[r])):
            if mask_grid[r][c] == 1:
                total += loss_grid[r][c]
                count += 1
    if count == 0:
        raise ValueError('All-masked batch: valid token count is 0!')
    return total / count

# ৩) Safe Per-sequence Mean (প্রতিটি Sequence সমান ওজন পায়)
def per_sequence_mean(loss_grid, mask_grid):
    seq_means = []
    for r in range(len(loss_grid)):
        s_total = 0.0
        s_count = 0
        for c in range(len(loss_grid[r])):
            if mask_grid[r][c] == 1:
                s_total += loss_grid[r][c]
                s_count += 1
        if s_count > 0:
            seq_means.append(s_total / s_count)
    if len(seq_means) == 0:
        raise ValueError('All-masked batch!')
    return sum(seq_means) / len(seq_means)

vt_clean = valid_token_mean(losses_clean, mask)
vt_nan = valid_token_mean(losses_with_nan, mask)
ps_nan = per_sequence_mean(losses_with_nan, mask)
assert abs(vt_clean - 3.2) < 1e-12 and abs(vt_nan - 3.2) < 1e-12
assert abs(ps_nan - 3.0) < 1e-12
print(f'Safe Valid-token Mean  : {vt_nan:.4f} (clean={vt_clean:.4f})')
print(f'Safe Per-sequence Mean : {ps_nan:.4f}')

class SequenceGRU(nn.Module):
    def __init__(self):
        super().__init__()
        self.recurrent = nn.GRU(1, 3, batch_first=True, dtype=torch.float64)
        self.head = nn.Linear(3, 1, dtype=torch.float64)

    def forward(self, X):
        if X.ndim != 3 or X.shape[1:] != (14, 1):
            raise ValueError("X[B,14,1]")
        output, _ = self.recurrent(X)
        return self.head(output[:, -1]).squeeze(-1)


def parameters(cell, head=None):
    record = {
        "w_ih": cell.weight_ih_l0.detach().tolist(),
        "w_hh": cell.weight_hh_l0.detach().tolist(),
        "b_ih": cell.bias_ih_l0.detach().tolist(),
        "b_hh": cell.bias_hh_l0.detach().tolist(),
    }
    if head is not None:
        record.update(
            head_weight=head.weight.detach()[0].tolist(),
            head_bias=head.bias.detach().item(),
        )
    return record


def sigmoid(x):
    return np.exp(-np.logaddexp(0, -x))


def manual(sequence, p, kind, length=None):
    x = np.asarray(sequence, dtype=float)
    length = len(x) if length is None else length
    if (
        x.ndim != 1
        or not len(x)
        or not np.isfinite(x).all()
        or not isinstance(length, int)
        or length < 1
        or length > len(x)
        or kind not in ["rnn", "gru", "lstm"]
    ):
        raise ValueError("Finite sequence, valid length/cell")
    W = np.asarray(p["w_ih"])
    U = np.asarray(p["w_hh"])
    a = np.asarray(p["b_ih"])
    b = np.asarray(p["b_hh"])
    rows = {"rnn": 3, "gru": 9, "lstm": 12}[kind]
    if (
        W.shape != (rows, 1)
        or U.shape != (rows, 3)
        or a.shape != (rows,)
        or b.shape != (rows,)
        or any(not np.isfinite(v).all() for v in [W, U, a, b])
    ):
        raise ValueError("Hidden3 PyTorch gate layout")
    h = np.zeros(3)
    c = np.zeros(3)
    trace = []
    for value in x[:length]:
        ih = W[:, 0] * value + a
        hh = U @ h + b
        if kind == "rnn":
            h = np.tanh(ih + hh)
            gates = {}
        elif kind == "gru":
            r = sigmoid(ih[:3] + hh[:3])
            z = sigmoid(ih[3:6] + hh[3:6])
            n = np.tanh(ih[6:] + r * hh[6:])
            h = (1 - z) * n + z * h
            gates = {"reset": r.tolist(), "update": z.tolist(), "candidate": n.tolist()}
        else:
            gates4 = ih + hh
            i = sigmoid(gates4[:3])
            f = sigmoid(gates4[3:6])
            g = np.tanh(gates4[6:9])
            o = sigmoid(gates4[9:])
            c = f * c + i * g
            h = o * np.tanh(c)
            gates = {
                "input": i.tolist(),
                "forget": f.tolist(),
                "candidate": g.tolist(),
                "output": o.tolist(),
            }
        trace.append(
            {
                "hidden": h.tolist(),
                "cell": c.tolist() if kind == "lstm" else [],
                "gates": gates,
            }
        )
    return trace


def recursive(model, history, mean, scale, horizon):
    prefix = list(history)
    if horizon < 1 or horizon > 7 or len(prefix) < 14:
        raise ValueError("History>=14, horizon1..7")
    result = []
    model.eval()
    with torch.no_grad():
        for _ in range(horizon):
            X = torch.tensor(
                (np.array(prefix[-14:]) - mean) / scale, dtype=torch.float64
            ).reshape(1, 14, 1)
            value = model(X).item() * scale + mean
            result.append(value)
            prefix.append(value)
    return result
